// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(actor.code.length == 0); // EOA so transfer never fails on receive

        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // settle in the SAME block: target block (block.number + 1) has NOT passed yet.
        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        // Rule: settling before the target block is never allowed (must revert).
        assertTrue(!ok, "settle succeeded before target block");
    }
}
